function graphContainer(sorted) {
  return el('div', { class: 'sigma-container', 'data-graph-count': String(sorted.length) });
}

function mountSigma(sorted) {
  const container = document.querySelector('.sigma-container');
  if (!container) return;
  sigmaInstance?.kill();
  const graph = new Graph();
  sorted.forEach((entity, index) => {
    const angle = (index / Math.max(sorted.length, 1)) * Math.PI * 2;
    const radius = 0.25 + (index % 3) * 0.12;
    graph.addNode(entity.id, {
      label: entity.name,
      x: entity.x / 700 - 0.5 || Math.cos(angle) * radius,
      y: entity.y / 520 - 0.5 || Math.sin(angle) * radius,
      size: 7 + entity.degree * 0.75,
      color: riskColor[entity.risk],
      risk: entity.risk,
      entityId: entity.id,
    });
  });
  edges.forEach(([source, target]) => {
    if (graph.hasNode(source) && graph.hasNode(target) && !graph.hasEdge(source, target)) graph.addEdge(source, target, { color: '#cbd8e8', size: 1.5, type: 'line' });
  });
  sigmaInstance = new Sigma(graph, container, {
    renderLabels: true,
    labelFont: 'DM Sans',
    labelSize: 12,
    labelColor: { color: '#162b47' },
    defaultNodeColor: '#0d5bd7',
    defaultEdgeColor: '#cbd8e8',
    minCameraRatio: 0.2,
    maxCameraRatio: 5,
    allowInvalidContainer: true,
  });
  sigmaInstance.on('clickNode', ({ node }) => { state.selected = node; render(); });
}
