async function saveManualFIR(){
  if(!supabaseConfigured){showToast(t('authNotConfigured'));return;}
  const form=document.querySelector('.manual-form');
  const value=(name)=>form.querySelector(`[name="${name}"]`)?.value?.trim()||'';
  const {data:{user}}=await supabase.auth.getUser();
  if(!user){showToast(t('authFailed'));return;}
  const sections=value('sections').split(',').map(x=>x.trim()).filter(Boolean);
  const {data:fir,error:firError}=await supabase.from('fir_cases').insert({fir_number:value('firNumber'),police_station:value('policeStation'),district:value('district'),incident_date:value('incidentDate')||null,sections,incident_summary:value('incidentSummary'),extraction_status:'manual',created_by:user.id}).select('id').single();
  if(firError){showToast(t('saveFailed'));return;}
  const subjectName=value('subjectName');
  if(subjectName){
    const {data:entity,error:entityError}=await supabase.from('entities').insert({entity_type:'person',display_name:subjectName,aliases:value('alias')?[value('alias')]:[],identifiers:{dob:value('dob'),address:value('address'),phone:value('phone'),vehicle:value('vehicle'),bank:value('bank')},created_by:user.id}).select('id').single();
    if(entityError){showToast(t('saveFailed'));return;}
    await supabase.from('fir_entities').insert({fir_id:fir.id,entity_id:entity.id,involvement:'subject'});
  }
  for(const item of state.manualEvidence){let storagePath=null;let sha256=null;if(item.file){const buffer=await item.file.arrayBuffer();const digest=await crypto.subtle.digest('SHA-256',buffer);sha256=Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,'0')).join('');const upload=await uploadPrivateEvidence({supabase,file:item.file,userId:user.id,sha256});if(upload.error){showToast(t('saveFailed'));return;}storagePath=upload.path;}const {error}=await supabase.from('evidence_items').insert({fir_id:fir.id,evidence_type:item.type,description:item.description,storage_path:storagePath,sha256,created_by:user.id});if(error){showToast(t('saveFailed'));return;}}
  const eventPayload=JSON.stringify({action:'fir.created',firId:fir.id,actor:user.id,at:new Date().toISOString()});
  const eventHash=await hashText(eventPayload);
  await supabase.from('audit_events').insert({actor_id:user.id,action:'fir.created',resource_type:'fir_case',resource_id:fir.id,change_summary:{firNumber:value('firNumber'),evidenceCount:state.manualEvidence.length},event_hash:eventHash});
  state.manualEvidence=[];
  showToast(t('caseSaved'));
  render();
}
